<?php require_once '../includes/config.php'; require_permission('support');$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$pdo->prepare('UPDATE support_tickets SET status=?,staff_reply=? WHERE id=?')->execute([post_str('status'),post_str('reply'),(int)$_POST['id']]);flash('success','Ticket updated.');redirect('support.php');}$rows=$pdo->query("SELECT t.*,u.name,u.email FROM support_tickets t JOIN users u ON u.id=t.user_id ORDER BY t.created_at DESC")->fetchAll();$title='Support';require '../includes/header.php';?><h1 class="section-title">Customer Support</h1><?php foreach($rows as $r):?><div class="panel p-4 mb-3"><strong>#<?=$r['id']?> <?=e($r['subject'])?></strong><div class="text-secondary"><?=e($r['name'])?> · <?=e($r['email'])?></div><p class="mt-2"><?=e($r['message'])?></p><form method="post" class="row g-2"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><div class="col-md-3"><select class="form-select" name="status"><option>open</option><option>in progress</option><option>resolved</option></select></div><div class="col-md-7"><input class="form-control" name="reply" value="<?=e($r['staff_reply'])?>" placeholder="Reply"></div><div class="col-md-2"><button class="btn btn-purple w-100">Update</button></div></form></div><?php endforeach;?><?php require '../includes/footer.php'; ?>